We have,
$\begin{array}{llll} 
\cos \left(\cot ^{-1}\left(\frac{1}{2}\right)\right) =\cot \left(\cos ^{-1} x\right) \\
\Rightarrow \cos \cos ^{-1} \frac{1}{\sqrt{5}} =\cot \cot ^{-1} \frac{x}{\sqrt{1-x^2}} \\
\Rightarrow \frac{1}{\sqrt{5}} =\frac{x}{\sqrt{1-x^2}} \\
\Rightarrow \sqrt{1-x^2} =\sqrt{5} x
\end{array}
On squaring both sides, we get
$\begin{array}{llll}
\Rightarrow 1-x^2 =5 x^2 \Rightarrow 1=6 x^2 \\
x x = \pm \frac{1}{\sqrt{6}} \\
x =\frac{1}{\sqrt{6}} \text { [neglecting -ve sign] }
\end{array}

We have,
$\begin{array}{r}
\tan ^{-1} \frac{1}{5}+\frac{1}{2} \sec ^{-1} x+\tan ^{-1} \frac{1}{8}=\frac{\pi}{8} \\
\Rightarrow \quad\left(\tan ^{-1} \frac{1}{5}+\tan ^{-1} \frac{1}{8}\right)+\frac{1}{2} \sec ^{-1} x=\frac{\pi}{8}
\end{array}
$\Rightarrow \quad \tan ^{-1}\left[\frac{\frac{1}{5}+\frac{1}{8}}{1-\frac{1}{5} \times \frac{1}{8}}\right]+\frac{1}{2} \sec ^{-1} x=\frac{\pi}{8}\begin{array}{ll}\Rightarrow & \tan ^{-1} \frac{13}{39}+\frac{1}{2} \sec ^{-1} x=\frac{\pi}{8} \\ \Rightarrow & 2 \tan ^{-1} \frac{13}{39}+\sec ^{-1} x=\frac{\pi}{4} \\ \Rightarrow & 2 \tan ^{-1} \frac{1}{3}+\sec ^{-1} x=\frac{\pi}{4} \\ \Rightarrow & \tan ^{-1} \frac{\frac{2}{3}}{1-\frac{1}{9}}+\sec ^{-1} x=\frac{\pi}{4} \\ \Rightarrow & \tan ^{-1} \frac{3}{4}+\sec ^{-1} x=\frac{\pi}{4}\end{array}
$\begin{array}{rr}\Rightarrow \quad & \tan ^{-1} \frac{3}{4}+\tan ^{-1} \sqrt{x^2-1}=\frac{\pi}{4} \\ \Rightarrow \quad & \tan ^{-1}\left[\frac{\frac{3}{4}+\sqrt{x^2-1}}{1-\frac{3}{4} \sqrt{x^2-1}}\right]=\frac{\pi}{4}\end{array}
$\begin{array}{cc}\Rightarrow & \frac{3+4 \sqrt{x^2-1}}{4-3 \sqrt{x^2-1}}=1 \\ \Rightarrow & 3+4 \sqrt{x^2-1}=4-3 \sqrt{x^2-1} \Rightarrow 7 \sqrt{x^2-1}=1 \\ \Rightarrow & \sqrt{x^2-1}=\frac{1}{7} \Rightarrow x^2-1=\frac{1}{49} \Rightarrow x^2=\frac{50}{49}\end{array}

Given equation is
$\begin{gathered}
\left(\tan ^{-1} x\right)^2+\left(\cot ^{-1} x\right)^2=\frac{5 \pi^2}{8} \\
\left(\tan ^{-1} x+\cot ^{-1} x\right)^2-2 \tan ^{-1} x \cdot \cot ^{-1} x=\frac{5 x^2}{8} \\
{\left[\because \tan ^{-1} x+\cot ^{-1} x=\frac{\pi}{2}\right]}
\end{gathered}\begin{aligned} & \Rightarrow \quad \frac{\pi^2}{4}-2 \tan ^{-1} x\left(\pi / 2-\tan ^{-1} x\right)=\frac{5 \pi^2}{8} \\ & \Rightarrow-2 \cdot \frac{\pi \tan ^{-1} x}{2}+2\left(\tan ^{-1} x\right)^2=\frac{5 \pi^2}{8}-\frac{\pi^2}{4} \\ & \Rightarrow \quad\left(\tan ^{-1} x\right)^2-\frac{\pi \tan ^{-1} x}{2}=\frac{3 \pi^2}{16}\end{aligned}\begin{array}{cc}\therefore \quad & \tan ^{-1} x=\frac{\frac{\pi}{2} \pm \sqrt{\frac{\pi^2}{4}+\frac{3 \pi^2}{4}}}{2} \\ \Rightarrow \quad & \tan ^{-1} x=\frac{\frac{\pi}{2} \pm \pi}{2} \\ & =\frac{3 \pi}{4},-\frac{\pi}{4}\end{array}
$\begin{array}{ll}\Rightarrow & x=\tan \left(\frac{3 \pi}{4}\right), \tan \left(-\frac{\pi}{4}\right) \\ \Rightarrow & x=-1,-1\end{array}

We have
$\sin ^{-1} x-\cos ^{-1} x=\frac{\pi}{6}$
Let $A=\sin ^{-1} x\begin{array}{ll}
\Rightarrow & x=\sin A, \cos A=\sqrt{1-x^2} \\
\text {and } & B=\cos ^{-1} x \\
\Rightarrow & x=\cos B, \sin B=\sqrt{1-x^2}
\end{array}
Now,
$\begin{aligned}
\sin (A-B) & =\sin A \cos B-\cos A \sin B \\
& =x \cdot x-\sqrt{1-x^2} \cdot \sqrt{1-x^2} \\
& =x^2-1+x^2 \\
\sin \left(\frac{\pi}{6}\right) & =2 x^2-1 \\
\Rightarrow 2 x^2-1 & =\frac{1}{2} \Rightarrow 2 x^2=\frac{3}{2} \Rightarrow x^2=\frac{3}{4} \\
\Rightarrow \quad x & =\frac{\sqrt{3}}{2}
\end{aligned}
